import subprocess, os, time

def run_with_pty(mod, dur_ms=800):
    # use script to simulate pty? Use unbuffer?
    # Try using python pty
    import pty
    master, slave = pty.openpty()
    proc = subprocess.Popen(["./executable","-m",mod,"--exit-after-time",f"{dur_ms}ms"], stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    out = b""
    start = time.time()
    while time.time() - start < 2:
        try:
            import select
            r,_,_ = select.select([master], [], [], 0.2)
            if r:
                data = os.read(master, 4096)
                if not data:
                    break
                out += data
            if proc.poll() is not None:
                # drain
                while True:
                    r,_,_ = select.select([master], [], [], 0.1)
                    if not r:
                        break
                    try:
                        d=os.read(master,4096)
                        if not d:
                            break
                        out+=d
                    except:
                        break
                break
        except Exception as e:
            break
    try:
        os.close(master)
    except:
        pass
    proc.terminate()
    try:
        return out.decode(errors='ignore')
    except:
        return str(out)

for mod in ["ansible","download"]:
    out = run_with_pty(mod, 1200)
    print(f"=== {mod} ===\n", out[:5000])
