# try to set winsize
def run_with_pty(mod, dur_ms=800):
    master, slave = pty.openpty()
    # set winsize 80x24
    winsize = struct.pack("HHHH", 24, 80, 0, 0)
    fcntl.ioctl(slave, termios.TIOCSWINSZ, winsize)
    proc = subprocess.Popen(["./executable","-m",mod,"--exit-after-time",f"{dur_ms}ms"], stdout=slave, stderr=slave, close_fds=True)
    os.close(slave)
    out = b""
    start = time.time()
    while time.time() - start < 3:
        r,_,_ = select.select([master], [], [], 0.2)
        if r:
            try:
                data = os.read(master, 8192)
                if not data:
                    break
                out += data
            except OSError:
                break
        if proc.poll() is not None:
            # drain a bit
            for _ in range(5):
                r,_,_ = select.select([master], [], [], 0.1)
                if not r:
                    break
                try:
                    out += os.read(master, 8192)
                except:
                    break
            break
    try:
        os.close(master)
    except:
        pass
    proc.wait(timeout=1)
    return out.decode(errors='ignore')

for mod in ["ansible","download","bootlog","composer"]:
    out = run_with_pty(mod, 1000)
