        "cargo-vendor.tar.gz","docker-image.tar","video.mkv","audio.mp3","document.pdf","report.docx"
    ];

    for _ in 0..rng.gen_range(5..15) {
        let file = files.choose(&mut rng).unwrap();
        // simulate download progress
        let mut progress = 0u8;
        while progress <= 100 {
            let size_mb = rng.gen_range(1.0..10.0);
            let speed = rng.gen_range(20.0..100.0);
            let eta = rng.gen_range(0..5);
            // Format similar to wget: "file  0%[                ] 1.81MiB    36.10MiB/s   eta 0s"
            // Use clear line \x1b[2K\x1b[0G
            let filled = (progress as usize * 16 / 100) as usize;
            let bar = format!("{}{}{}", "=".repeat(filled.saturating_sub(1)), if filled>0 { "█" } else { "" }, " ".repeat(16 - filled));
            // Actually original uses "█" and spaces inside brackets with percentages
            print!("\x1b[2K\x1b[0G{:<20} {:3}%[{:16}] {:.2}MiB    {:.2}MiB/s   eta {}s", file, progress, bar, size_mb, speed, eta);
