            sleep_with_speed(50, speed_factor, &mut instant_remaining);
            if should_exit(global_start, exit_after_time) { return false; }
            let inc = rng.gen_range(1..8);
            progress = progress.saturating_add(inc);
            if progress > 100 { progress = 100; break; }
        }
        println!();
        println!();
        sleep_with_speed(100, speed_factor, &mut instant_remaining);
        if should_exit(global_start, exit_after_time) { return false; }
