use super::*;
use rand::Rng;
use std::time::{Instant, Duration};

pub fn run(speed_factor: f64, instant_lines: usize, global_start: Instant, exit_after_time: Option<Duration>) -> bool {
    let mut rng = rand::thread_rng();
    let mut instant_remaining = instant_lines;

    let start_addr: u64 = rng.gen_range(0x0000000000000000..0xffffffffffffffff);
    let mut addr = start_addr;
    let lines = rng.gen_range(80..250);

    for _ in 0..lines {
        let mut bytes = Vec::new();
        for _ in 0..16 {
            bytes.push(rng.gen_range(0..=255u8));
        }
        // hex part
        let hex_part_1 = bytes[0..8].iter().map(|b| format!("{:02x}", b)).collect::<Vec<_>>().join(" ");
        let hex_part_2 = bytes[8..16].iter().map(|b| format!("{:02x}", b)).collect::<Vec<_>>().join(" ");
        let ascii_part: String = bytes.iter().map(|&b| {
            if b >= 32 && b <= 126 {
                b as char
            } else {
                '.'
            }
        }).collect();

        println!("{:016x}  {}  {}  |{}|", addr, hex_part_1, hex_part_2, ascii_part);
        addr += 16;
        sleep_with_speed(20, speed_factor, &mut instant_remaining);
        if should_exit(global_start, exit_after_time) { return false; }
    }

    true
}
