    let mut rng = rand::thread_rng();
    let mut instant_remaining = instant_lines;

    let tasks = [
        "Synthesizing Gravity",
        "Calibrating Blue Skies",
        "Relaxing Splines",
        "Extracting Resources",
        "Gesticulating Mimes",
        "Reticulating Splines",
        "Generating Jobs",
        "Charging Flux Capacitors",
        "Optimizing Tax Rates",
        "Building Roads",
        "Zoning Residential",
        "Planting Trees",
    ];

    let spinners = ["/","-","\\","|"];

    let total_tasks = rng.gen_range(5..12);
    for _ in 0..total_tasks {
        let task = tasks.choose(&mut rng).unwrap();
        let will_abort = rng.gen_bool(0.15);
        for i in 0..rng.gen_range(15..40) {
            let sp = spinners[i % spinners.len()];
            print!("\r[ ] {}... {}", task, sp);
