    if should_exit(global_start, exit_after_time) { return false; }

    let prefixes = ["google","azurerm","aws","azure","gcp"];
    let middles = ["compute","storage","iam","network","sql","bigquery","container","cloudbuild","clouddeploy","workstations","apigee","bot","sentinel","logz","cosmosdb","cdn","stream","analytics","app","service","hpc","cache","dev","test","linux","virtual","machine"];
    let suffixes = ["mediator","containerizer","securer","regulator","planner","viewer","creator","navigator","versioner","programmer","updater","enumerator","diagnostics","source","refresher","detector","producer","wrapper","scout","conservator","surveyor","leader","synthesizer","visualizer","creator","regulator","mediator"];

    let actions = ["Creating...","Creation complete after 0s","Creation complete after 1s","Modifying...","Modifications complete after 0s","Modifications complete after 1s","Destroying...","Destruction complete after 1s","Still modifying... [id={id}, 0s elapsed]","Still modifying... [id={id}, 1s elapsed]","Refreshing state..."];

