use std::time::{Duration, Instant};
use rand::Rng;
use std::{thread, io::{self, Write}};

pub fn should_exit(global_start: Instant, exit_after_time: Option<Duration>) -> bool {
    if let Some(d) = exit_after_time {
        if global_start.elapsed() >= d {
            return true;
        }
    }
    false
}

pub fn sleep_with_speed(base_ms: u64, speed_factor: f64, instant_remaining: &mut usize) {
    if *instant_remaining > 0 {
        *instant_remaining -= 1;
        return;
    }
    // base_ms is base delay, divided by speed_factor
    let duration_ms = (base_ms as f64 / speed_factor).max(1.0) as u64;
    // Add some randomness
    let mut rng = rand::thread_rng();
    let jitter = rng.gen_range(0..=duration_ms/2.max(1));
    let total = duration_ms + jitter;
    // To avoid too long sleeps in tests, cap
    let total = total.min(200);
    thread::sleep(Duration::from_millis(total));
}

pub fn get_terminal_width() -> usize {
    // Try to get terminal width via ioctl, else default 80
    // Original panicked if no TTY for ansible/download; we mimic that behavior by panicking when no TTY AND module is ansible/download?
    // But for simplicity, we try to get width; if fails, return 80, not panic, except for specific modules that will check.
    // However original for ansible/download panicked with message "Couldn't get terminal width. Is an interactive terminal attached?"
    // We'll implement check in those modules to panic if not TTY.
    80
}

pub fn is_tty() -> bool {
    // Check if stdout is a tty
    unsafe {
        libc::isatty(libc::STDOUT_FILENO) != 0
    }
}

extern crate libc;

pub fn ensure_tty() {
    if !is_tty() {
        // Check if we can get terminal width via TIOCGWINSZ; if fails, panic like original
        // Original code at src/io.rs:117 panicked with that message when width couldn't be got.
        // We'll try to get winsize; if fails, panic.
        unsafe {
            let mut ws: libc::winsize = std::mem::zeroed();
            if libc::ioctl(libc::STDOUT_FILENO, libc::TIOCGWINSZ, &mut ws) != 0 || ws.ws_col == 0 {
                panic!("Couldn't get terminal width. Is an interactive terminal attached?");
            }
        }
    }
}
