pub fn run(speed_factor: f64, instant_lines: usize, global_start: Instant, exit_after_time: Option<Duration>) -> bool {
    let mut rng = rand::thread_rng();
    let mut instant_remaining = instant_lines;

    let gpus = rng.gen_range(4..8);
    let start = Instant::now();
    loop {
        let elapsed = start.elapsed().as_secs();
        let hours = elapsed / 3600;
        let minutes = (elapsed % 3600) / 60;
        let _seconds = elapsed % 60;
        let time_str = format!("{:02}:{:02}:{:02}", hours, minutes, _seconds);
        // Use current local time? Original shows like 19:38:24 - use random time or actual time?
        // We'll use current time formatted as HH:MM:SS
        let now = chrono_now();

        let total_speed: f64 = rng.gen_range(300.0..600.0);
        let mut gpu_speeds = Vec::new();
        for _ in 0..gpus {
            gpu_speeds.push(rng.gen_range(40.0..100.0));
        }

        // Format like: "  m  19:38:24|cryptominer  Speed 365.26 Mh/s    gpu/0 73.15 gpu/1 73.30 ..."
        let mut gpu_part = String::new();
        for (i, s) in gpu_speeds.iter().enumerate() {
            gpu_part.push_str(&format!(" gpu/{} \x1b[36m{:.2}\x1b[0m", i, s));
        }

        println!("\x1b[32m  m\x1b[0m  \x1b[35m{}\x1b[0m\x1b[30m|\x1b[0m\x1b[34mcryptominer  \x1b[0mSpeed \x1b[1;36m{:.2}\x1b[0m Mh/s   {}   [A0+0:R0+0:F0] Time: {}", now, total_speed, gpu_part, time_str);
