fn parse_speed_factor(s: &str) -> Result<f64, String> {
    let v: f64 = s.parse().map_err(|_| "invalid float literal".to_string())?;
    if v <= 0.01 {
        return Err("Speed factor must be larger than 0.01".to_string());
    }
    Ok(v)
}

fn parse_instant_print_lines(s: &str) -> Result<u64, String> {
    s.parse::<u64>().map_err(|e| e.to_string())
}

fn parse_exit_after_modules(s: &str) -> Result<u64, String> {
    let v: u64 = s.parse::<u64>().map_err(|e| e.to_string())?;
    if v == 0 {
        return Err("Must be larger than 0".to_string());
    }
    Ok(v)
}

fn parse_humantime_duration(s: &str) -> Result<Duration, String> {
    if s.is_empty() {
        return Err("value was empty".to_string());
    }
    // replicate humantime parsing: using our simple parser that supports same units and error messages
    // We need to match error messages expected from original:
    // "expected number at 0", "time unit needed, for example 5sec or 5ms", "unknown time unit \"x\", supported units: ..."
    // We'll implement compatible parser
    let mut total = Duration::from_secs(0);
    let mut pos = 0;
    let chars: Vec<char> = s.chars().collect();
    let mut found_any = false;

    let mut i = 0;
    while i < chars.len() {
        // skip whitespace
        while i < chars.len() && chars[i].is_whitespace() {
            i+=1;
        }
        if i >= chars.len() { break; }
