    let mut i = 0;
    while i < chars.len() {
        while i < chars.len() && chars[i].is_whitespace() {
            i+=1;
        }
        if i >= chars.len() { break; }
        let num_start = i;
        let mut has_digit = false;
        while i < chars.len() && (chars[i].is_ascii_digit() || chars[i]=='.') {
            if chars[i].is_ascii_digit() { has_digit = true; }
            i+=1;
